"""converts a given Text to a upper camel case text
    this is a example -> ThisIsAExample"""
def toUpperCamelCase(text: Any) -> object {
    splittedText = text.split();
    upperCamelCase = '';
    for t in splittedText {
        upperCamelCase += t[0:1].capitalize();
        upperCamelCase += t[1:];
    }
    return upperCamelCase;
}

""" Converts a string of binary numbers to their two's compliment integer representation """
def convert_twos_compliment(bin_str: Any) -> object {
    length = len(bin_str);
    if (bin_str[0] == '0') {
        return int(bin_str, 2);
    } else {
        return (int(bin_str, 2) - (1 << length));
    }
}

