def my_round_even(number: Any) -> object {
    import from decimal { Decimal, ROUND_HALF_EVEN }
    d = Decimal.from_float(number).quantize(1, rounding=ROUND_HALF_EVEN);
    return int(d);
}

"""
    Titleizes a string, aka transforms it from underscored to English title
    format
    """
def titleize(s: str) -> str {
    s = s.replace('_', ' ');
    words = s.split(' ');
    new_words = [(w[0].upper() + w[1:]) for w in words];
    return ' '.join(new_words);
}
